fn hwchicken_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    let mut l_inputstr_s = Val::from("");
    if (ctx.var("halloween").get()? == 102 || ctx.var("halloween").get()? == 103) {
        ctx.lines(args![
            "Oh, this must be Chicken Masta's chicken.",
            "I should insert the magic word."
        ])?;
        ctx.next()?;
        let (input, status) = runtime::input_text(ctx, None, None)?;
        l_inputstr_s = input;
        if l_inputstr_s.clone() == "Return" {
            ctx.call(Function::Emotion, vec![ctx.constant("ET_HUK")?])?;
            ctx.call(Function::NpcSpecialEffect, vec![ctx.constant("EF_TELEPORTATION")?])?;
            ctx.mes("The magic spell has been casted.")?;
            ctx.var("halloween").set(Val::from(103))?;
            ctx.call(
                Function::DisableNpc,
                vec![(Val::from("Masta's chicken#") + ctx.call(Function::StrNpcInfo, vec![Val::from(1)])?)],
            )?;
            ctx.close_window()?;
            ctx.call(Function::Sleep, vec![Val::from(180000)])?;
            ctx.call(
                Function::EnableNpc,
                vec![(Val::from("Masta's chicken#") + ctx.call(Function::StrNpcInfo, vec![Val::from(1)])?)],
            )?;
            return Err(Stop::End);
        } else {
            ctx.lines_as(
                ctx.call(Function::StrCharInfo, vec![Val::from(0)])?,
                args!["Hm...I must have misspelled."],
            )?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
    } else {
        ctx.mes("Drowsing chicken.")?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
}

