fn familiar_06_hw01_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.lines_as(
        "Familiar",
        args![
            "Hello.",
            "I'm Loli Ruri's faithful and cute Familiar.",
            "Do you have an invitation from Loli Ruri?",
            "That's a kind of^4d4dffa special ticket to Niflheim^000000.."
        ],
    )?;
    ctx.next()?;
    if Val::from(runtime::select_values(ctx, &[Val::from("Yes, I do.:No, I don't.")])?) == 1 {
        ctx.lines_as(
            "Familiar",
            args!["Do you want to go to Niflheim?", "It's available during Halloween."],
        )?;
        ctx.next()?;
        if Val::from(runtime::select_values(ctx, &[Val::from("Yes, I do:No, I don't.")])?) == 1 {
            if ctx.call(Function::CountItem, vec![Val::from(7460)])?.number()? > 0 {
                ctx.lines_as("Familiar", args!["I checked your ticket.", "You can go there now"])?;
                ctx.call(Function::DelItem, vec![Val::from(7460), Val::from(1)])?;
                ctx.close_window()?;
                ctx.call(Function::Warp, vec![Val::from("nif_in"), Val::from(18), Val::from(20)])?;
                return Err(Stop::End);
            } else {
                ctx.lines_as(
                    "Familiar",
                    args![
                        "You're a liar.",
                        "You don't have the ticket!",
                        "I'll suck up all your blood, you liar!"
                    ],
                )?;
                ctx.call(Function::PercentHeal, vec![Val::from(-20), Val::from(0)])?;
                ctx.call(
                    Function::Emotion,
                    vec![
                        ctx.constant("ET_HUK")?,
                        Val::from(ctx.call(Function::GetCharacterId, vec![Val::from(0)])?.is_true()),
                    ],
                )?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
        }
        ctx.lines_as(
            "Familiar",
            args!["Ok.", "Actually, it's useless to have a special ticket to Niflheim."],
        )?;
        ctx.close_window()?;
        return Err(Stop::End);
    }
    ctx.lines_as(
        "Familiar",
        args![
            "Ok.",
            "If you want to ask something, give a piece of pumpkin pie to Loli Ruri.",
            "He likes it."
        ],
    )?;
    ctx.close_window()?;
    return Err(Stop::End);
}

pub fn familiar_06_hw01(ctx: &Ctx) -> Script {
    familiar_06_hw01_body(ctx, Vec::new()).map(|_| ())
}
